const views=[...document.querySelectorAll('.view')],nav=[...document.querySelectorAll('.navlink')];
function showView(id){views.forEach(v=>v.classList.toggle('active',v.id===id));nav.forEach(n=>n.classList.toggle('active',n.dataset.view===id));document.querySelector('nav').classList.remove('open');document.getElementById('menuBtn').setAttribute('aria-expanded','false');window.scrollTo({top:0,behavior:'smooth'});history.replaceState(null,'','#'+id)}
document.querySelectorAll('[data-view],[data-go]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view||b.dataset.go)));
const menu=document.getElementById('menuBtn');menu.addEventListener('click',()=>{const open=document.querySelector('nav').classList.toggle('open');menu.setAttribute('aria-expanded',open)});
const toast=document.getElementById('toast');function notify(msg){toast.textContent=msg;toast.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>toast.classList.remove('show'),2400)}
let step=1;const stepButtons=[...document.querySelectorAll('.steps button')],progress=document.querySelector('.progress span'),stepLabel=document.querySelector('.step-label');
function setStep(n){step=Math.max(0,Math.min(5,n));stepButtons.forEach((b,i)=>{b.classList.toggle('current',i===step);b.classList.toggle('done',i<step);b.querySelector('b').textContent=i<step?'✓':i+1});progress.style.width=((step+1)/6*100)+'%';stepLabel.textContent=`ধাপ ${step+1} / ৬`;if(step!==1) notify('এই প্রোটোটাইপে pH ধাপের ইন্টারফেস দেখানো হচ্ছে')}
stepButtons.forEach((b,i)=>b.addEventListener('click',()=>setStep(i)));document.getElementById('nextBtn').addEventListener('click',()=>{const picked=document.querySelector('input[name=ph]:checked');if(!picked&&step===1)return notify('একটি রঙ বেছে নিন, অথবা “বুঝতে পারছি না” চাপুন');setStep(step+1)});document.getElementById('backBtn').addEventListener('click',()=>setStep(step-1));document.getElementById('unknownBtn').addEventListener('click',()=>{document.querySelectorAll('input[name=ph]').forEach(i=>i.checked=false);notify('ছবি দিয়ে যাচাইয়ের অপশন পরবর্তী সংস্করণে যুক্ত হবে')});
document.querySelectorAll('.tasks input').forEach(i=>i.addEventListener('change',()=>notify(i.checked?'কাজটি সম্পন্ন হিসেবে রাখা হয়েছে':'কাজটি আবার তালিকায় রাখা হয়েছে')));
document.getElementById('langBtn').addEventListener('click',()=>notify('English interface is prepared as the next language layer'));
const initial=location.hash.slice(1);if(views.some(v=>v.id===initial))showView(initial);
